CREATE OR REPLACE FUNCTION public.complete_saved_search_digest(p_id uuid, p_attempt integer, p_outcome text, p_provider_message_id text DEFAULT NULL::text, p_error text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
